import{_ as i,o as s,c as e,ae as t}from"./chunks/framework.Dn7Y7LSn.js";const k=JSON.parse('{"title":"Episode 6: Utilizing Packagist and Packages","description":"","frontmatter":{},"headers":[],"relativePath":"module-2/packagist.md","filePath":"module-2/packagist.md"}'),p={name:"module-2/packagist.md"};function n(o,a,c,l,d,r){return s(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="episode-6-utilizing-packagist-and-packages" tabindex="-1">Episode 6: Utilizing Packagist and Packages <a class="header-anchor" href="#episode-6-utilizing-packagist-and-packages" aria-label="Permalink to &quot;Episode 6: Utilizing Packagist and Packages&quot;">​</a></h1><p><strong>Packagist</strong> হলো কম্পোজারের জন্য একটি কমিউনিটি-ড্রিভেন (community-driven) প্যাকেজ রিপোজিটরি (repository), যেখানে রয়েছে হাজার হাজার পিএইচপি প্যাকেজ।</p><p><code>packagist.org</code> সাইট থেকে আমরা যে কোনো প্যাকেজ সার্চ দিয়ে বের করে আনতে পারব।</p><p>কমান্ড লাইন থেকে নিচের কমান্ডটি লিখে <code>Enter</code> প্রেস করলে আমরা available প্যাকেজগুলো দেখতে পাব:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> faker</span></span></code></pre></div><p>এবার আমরা আমাদের প্রয়োজনীয় প্যাকেজগুলো ইন্সটল করতে পারি:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fakerphp/faker</span></span></code></pre></div><p>Packagist থেকে প্যাকেজ ইন্সটলের সময় কয়েকটা জিনিস মাথায় রাখতে হবে:</p><ol><li>প্যাকেজটিকে অ্যাকটিভলি মেইনটেইন (actively maintain) করা হচ্ছে কিনা।</li><li>ভার্সনগুলো ঠিকমতো আপডেট হচ্ছে কিনা।</li><li>এতে আগে কোনো সমস্যা বা বাগ (bug) পাওয়া গিয়েছিল কিনা।</li><li>সিকিউরিটি (security) নিয়ে কোনো ঝুঁকি বা রিস্ক আছে কিনা।</li></ol><p>packagist.org ছাড়াও <code>github</code>, <code>repman</code> ইত্যাদি রিপোজিটরি দিয়েও আমরা কম্পোজারের মাধ্যমে প্যাকেজ ইন্সটল করতে পারি।</p><p>এমনকি আমরা চাইলে আমাদের নিজেদের তৈরি করা কোনো প্যাকেজও Packagist-এ সাবমিট (submit) করে পুরো কমিউনিটির জন্য উন্মুক্ত করতে পারি।</p>',11)])])}const h=i(p,[["render",n]]);export{k as __pageData,h as default};
